import{_ as a,o as i,c as l,a8 as t}from"./chunks/framework.CiGKN4gy.js";const u=JSON.parse('{"title":"规则说明","description":"","frontmatter":{"title":"规则说明","lang":"zh-CN"},"headers":[],"relativePath":"zh-cn/advance/rule.md","filePath":"zh-cn/advance/rule.md","lastUpdated":1790353258000}'),o={name:"zh-cn/advance/rule.md"};function r(s,e,c,p,d,n){return i(),l("div",{"data-pagefind-body":!0,"data-pagefind-meta":"base64:JTdCJTIydGl0bGUlMjIlM0ElMjIlRTglQTclODQlRTUlODglOTklRTglQUYlQjQlRTYlOTglOEUlMjIlMkMlMjJsYW5nJTIyJTNBJTIyemgtQ04lMjIlMkMlMjJkYXRlJTIyJTNBMTc5MDM1MzI1ODAwMCU3RA=="},[...e[0]||(e[0]=[t('<h1 id="规则说明" tabindex="-1">规则说明 <a class="header-anchor" href="#规则说明" aria-label="Permalink to &quot;规则说明&quot;">​</a></h1><p>本模块使用下列几种配置文件，所有的配置文件必须在同一目录下并保证 nginx 对其有读取权限。</p><ul><li>IP 白名单，文件名为 <code>white-ipv4</code> 和 <code>white-ipv6</code>。</li><li>IP 黑名单，文件名为 <code>ipv4</code> 和 <code>ipv6</code>。</li><li>Url 白名单，文件名为 <code>white-url</code>。</li><li>Url 黑名单，文件名为 <code>url</code>。</li><li>Get 参数黑名单，文件名为 <code>args</code>。</li><li>Post 请求体黑名单，文件名为 <code>post</code>。</li><li>UserAgent 黑名单，文件名为 <code>user-agent</code>。</li><li>Cookie 黑名单，文件名为 <code>cookie</code>。</li><li>Referer 白名单，文件名为 <code>white-referer</code>。</li><li>Referer 黑名单，文件名为 <code>referer</code>。</li></ul><div class="tip custom-block"><p class="custom-block-title">注意</p><p>有些规则文件需要书写正则表达式，书写时每行一个正则表达式， 正则表达式遵循 <a href="http://www.pcre.org/current/doc/html/pcre2syntax.html" target="_blank" rel="noreferrer">PCRE 标准</a>。</p></div><div class="tip custom-block"><p class="custom-block-title">注意</p><p>高级规则仅在开发版中可用。</p></div><h2 id="ip白名单" tabindex="-1">ip白名单 <a class="header-anchor" href="#ip白名单" aria-label="Permalink to &quot;ip白名单&quot;">​</a></h2><p>ip 白名单包括下面两个文件。</p><ul><li>ipv4 白名单，文件名为 <code>white-ipv4</code>。</li><li>ipv6 白名单，文件名为 <code>white-ipv6</code>。</li></ul><p>书写时一行指定一个 IP 地址或者 IP 地址块。ipv4 地址必须使用「点分十进制表示法」， ipv6 地址必须使用 「冒号十六进制表示法」。下面举一些例子。</p><p>指定单个 ipv4 地址。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>192.168.2.1</span></span></code></pre></div><p>指定一个 ipv4 地址块。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>192.168.2.0/24</span></span></code></pre></div><p>指定单个 ipv6 地址。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>FE80::1000</span></span></code></pre></div><p>指定一个 ipv6 地址块。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>FE80::/10</span></span></code></pre></div><h2 id="ip黑名单" tabindex="-1">IP黑名单 <a class="header-anchor" href="#ip黑名单" aria-label="Permalink to &quot;IP黑名单&quot;">​</a></h2><p>IP 黑名单包括下面两个文件。</p><ul><li>ipv4 黑名单，文件名为 <code>ipv4</code>。</li><li>ipv6 黑名单，文件名为 <code>ipv6</code>。</li></ul><p>写法同 <a href="#ip白名单">ip 白名单</a>。</p><h2 id="url白名单" tabindex="-1">url白名单 <a class="header-anchor" href="#url白名单" aria-label="Permalink to &quot;url白名单&quot;">​</a></h2><p>Url 白名单的文件名为 <code>white-url</code>，书写规则时每行指定一个正则表达式， Url 被任何一个正则表达式匹配到就会直接放行，不进行后续的检查。</p><h2 id="url黑名单" tabindex="-1">url黑名单 <a class="header-anchor" href="#url黑名单" aria-label="Permalink to &quot;url黑名单&quot;">​</a></h2><p>Url 黑名单的文件名为 <code>url</code>，书写规则时每行指定一个正则表达式， Url 被任何一个正则表达式匹配到就会被拦截，返回 403 状态码。</p><h2 id="get参数黑名单" tabindex="-1">get参数黑名单 <a class="header-anchor" href="#get参数黑名单" aria-label="Permalink to &quot;get参数黑名单&quot;">​</a></h2><p>Get 参数黑名单的文件名为 <code>args</code>，书写规则时每行指定一个正则表达式， Get 参数被任何一个正则表达式匹配到就会被拦截，返回 403 状态码。</p><h2 id="post请求体黑名单" tabindex="-1">post请求体黑名单 <a class="header-anchor" href="#post请求体黑名单" aria-label="Permalink to &quot;post请求体黑名单&quot;">​</a></h2><p>Post 请求体黑名单的文件名为 <code>post</code>，书写规则时每行指定一个正则表达式， Post 请求体内的内容被任何一个正则表达式匹配到就会被拦截，返回 403 状态码。</p><div class="warning custom-block"><p class="custom-block-title">警告</p><p>有时本模块不会执行 Post 请求体检查，详见<a href="/ngx_waf-docs/zh-cn/guide/faq.html#post检测失效">常见问题与解答</a>。</p></div><h2 id="user-agent黑名单" tabindex="-1">user-agent黑名单 <a class="header-anchor" href="#user-agent黑名单" aria-label="Permalink to &quot;user-agent黑名单&quot;">​</a></h2><p>UserAgent 黑名单的文件名为 <code>user-agent</code>，书写规则时每行指定一个正则表达式， UserAgent 被任何一个正则表达式匹配到就会被拦截，返回 403 状态码。</p><h2 id="cookie黑名单" tabindex="-1">cookie黑名单 <a class="header-anchor" href="#cookie黑名单" aria-label="Permalink to &quot;cookie黑名单&quot;">​</a></h2><p>Cookie 黑名单的文件名为 <code>cookie</code>，书写规则时每行指定一个正则表达式， Cookie 被任何一个正则表达式匹配到就会被拦截，返回 403 状态码。</p><h2 id="referer白名单" tabindex="-1">referer白名单 <a class="header-anchor" href="#referer白名单" aria-label="Permalink to &quot;referer白名单&quot;">​</a></h2><p>Referer 白名单的文件名为 <code>white-referer</code>，书写规则时每行指定一个正则表达式， Referer 被任何一个正则表达式匹配到就会直接放行，不进行后续的检查。</p><h2 id="referer黑名单" tabindex="-1">referer黑名单 <a class="header-anchor" href="#referer黑名单" aria-label="Permalink to &quot;referer黑名单&quot;">​</a></h2><p>Referer 黑名单的文件名为 <code>referer</code>，书写规则时每行指定一个正则表达式， Referer 被任何一个正则表达式匹配到就会被拦截，返回 403 状态码。</p>',38)])])}const g=a(o,[["render",r]]);export{u as __pageData,g as default};
